function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readJson(text) {
  return new Promise((resolve, reject) => {
    try { resolve(JSON.parse(text)); }
    catch (error) { reject(error); }
  });
}

