async function loadProduct(id) {
  try {
    const response = await fetch(`/api/products/${id}`);
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return await response.json();
  } catch (error) {
    console.error("falhou ao carregar", error);
    return null;
  }
}

