function timeout(ms) {
  return new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`Tempo esgotado após ${ms} ms`)), ms),
  );
}

const response = await Promise.race([fetch("/api/report"), timeout(5000)]);

// Alternativa que também cancela a requisição:
const report = await fetch("/api/report", { signal: AbortSignal.timeout(5000) });

async function fetchCep(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  if (data.erro) throw new Error("CEP não encontrado");
  return data;
}

try {
  const address = await Promise.any([
    fetchCep(`https://viacep.com.br/ws/${cep}/json/`),
    fetchCep(`https://brasilapi.com.br/api/cep/v2/${cep}`),
    fetchCep(`https://cep.awesomeapi.com.br/json/${cep}`),
  ]);
  console.log(address);
} catch (error) {
  // AggregateError: todas falharam
  console.error(error.errors);
}
